import sys

def process_spell():
    lines = sys.stdin.read().splitlines()
    result = []

    for i, line in enumerate(lines):
        stripped_line = line.lstrip()
        if stripped_line.startswith('#'):
            # Preserve spaces in amplifying lines
            result.append(line)
        else:
            # Remove spaces in non-amplifying lines
            result.append(stripped_line)

    # Join lines while preserving newlines between amplifying lines
    output = []
    for i in range(len(result)):
        if i > 0 and not result[i].startswith('#') and not result[i-1].startswith('#'):
            output[-1] += result[i]
        else:
            output.append(result[i])

    # Print the result with newlines
    for line in output:
